import json
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=max(cnt,key=lambda c:(cnt[c],c)); 
    # noise = most frequent other colors; block colors = least frequent distinct ones
    others=[c for c in cnt if c!=bg]
    others.sort(key=lambda c:cnt[c])
    seen=[[False]*W for _ in range(H)]
    best=None
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c==bg or not others or cnt[c]>100 or seen[i][j]: continue
            stack=[(i,j)]; seen[i][j]=True; cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and g[nx][ny]==c:
                            seen[nx][ny]=True; stack.append((nx,ny))
            n=len(cells)
            if best is None or n>best['n']: best={'c':c,'n':n}
    return [[best['c']]*3 for _ in range(3)]

